package com.bplus.share;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class Unpair{
 private static final ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();private static boolean started;private static String me(){return Store.get("deviceId","");}private static String slot(String id){return "unpair_"+id;}private static byte[] key(JSONObject peer)throws Exception{return UnpairWire.key(me(),Store.token(),peer.getString("id"),peer.getString("token"));}public static String epoch(JSONObject peer)throws Exception{String e=peer.optString("pairEpoch");return e.matches("[a-f0-9]{64}")?e:UnpairWire.legacy(me(),Store.token(),peer.getString("id"),peer.getString("token"));}
 public static synchronized void start(){if(started)return;started=true;timer.scheduleWithFixedDelay(()->sweep(),1,15,TimeUnit.SECONDS);}public static void kick(){start();timer.execute(()->sweep());}
 public static JSONObject prepare(String id)throws Exception{JSONObject peer=Store.peerById(id);if(peer==null)return null;JSONObject n=new JSONObject().put("v",1).put("from",me()).put("to",id).put("epoch",epoch(peer)).put("event",Recall.secret());n.put("mac",UnpairWire.mac(n,key(peer),false));return new JSONObject().put("peer",new JSONObject(peer.toString())).put("notice",n).put("pending",true);}
 public static void index(String id,android.content.SharedPreferences.Editor edit)throws Exception{JSONArray a=new JSONArray(Store.get("unpairIds","[]"));boolean has=false;for(int i=0;i<a.length();i++)if(id.equals(a.optString(i)))has=true;if(!has)a.put(id);edit.putString("unpairIds",a.toString());}
 public static String tombSlot(String id){return slot(id);}public static JSONObject load(String id)throws Exception{String raw=Store.get(slot(id),"");return raw.isEmpty()?null:new JSONObject(raw);}
 public static void paired(JSONObject peer)throws Exception{JSONObject t=load(peer.getString("id"));if(t!=null){if(epoch(peer).equals(t.getJSONObject("notice").getString("epoch")))throw new IOException("Revoked pairing epoch. Pair again with updated apps.");}}
 public static JSONObject receive(JSONObject n)throws Exception{synchronized(Store.class){String from=n.getString("from");if(!me().equals(n.getString("to"))||from.equals(me()))throw new IOException("Wrong notice target");JSONObject t=load(from),peer=Store.peerById(from);if(peer==null){if(t==null)throw new IOException("Unknown pairing");peer=t.getJSONObject("peer");}if(!epoch(peer).equals(n.getString("epoch"))||!UnpairWire.verify(n,key(peer),false))throw new IOException("Invalid notice authentication");JSONObject ack=UnpairWire.ack(n,key(peer));if(Store.peerById(from)!=null)Store.applyRemoteUnpair(from,new JSONObject().put("peer",peer).put("notice",n).put("pending",false));return ack;}}
 public static void acknowledged(JSONObject ack)throws Exception{synchronized(Store.class){String id=ack.getString("from");JSONObject t=load(id);if(t==null||!me().equals(ack.getString("to")))throw new IOException("Unknown ack");JSONObject n=t.getJSONObject("notice"),peer=t.getJSONObject("peer");if(!n.getString("event").equals(ack.getString("event"))||!n.getString("epoch").equals(ack.getString("epoch"))||!UnpairWire.verify(ack,key(peer),true))throw new IOException("Bad ack");t.put("pending",false);Store.durable(slot(id),t.toString());}}
 public static JSONObject hello(JSONObject b)throws Exception{if(!b.optString("op").equals("hello"))return null;String from=b.optString("from");JSONObject t=load(from);if(t==null||Store.peerById(from)!=null||!me().equals(t.getJSONObject("notice").optString("from")))return null;JSONObject p=t.getJSONObject("peer");if(!p.getString("token").equals(b.optString("senderToken"))||!Store.token().equals(b.optString("targetToken")))throw new IOException("Wrong tombstone credentials");return new JSONObject().put("v",2).put("unpair",t.getJSONObject("notice"));}
 public static boolean reply(JSONObject reply,JSONObject peer)throws Exception{JSONObject notice=reply.optJSONObject("unpair");if(notice==null)return false;JSONObject ack=receive(notice);try{post(peer,"/pairing/unpair-ack",ack);}catch(Exception ignored){}return true;}
 private static JSONObject post(JSONObject peer,String path,JSONObject body)throws Exception{HttpURLConnection h=(HttpURLConnection)new URL("http://"+peer.getString("ip")+":"+peer.optInt("port",Store.PORT)+path).openConnection();h.setInstanceFollowRedirects(false);h.setConnectTimeout(2500);h.setReadTimeout(4000);try{h.setRequestMethod("POST");h.setDoOutput(true);h.setRequestProperty("Content-Type","application/json");byte[] bytes=body.toString().getBytes("UTF-8");h.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=h.getOutputStream()){out.write(bytes);}if(h.getResponseCode()!=200)throw new IOException("Unpair unavailable");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=h.getInputStream()){byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1){if(out.size()+n>4096)throw new IOException("Reply too large");out.write(b,0,n);}}return new JSONObject(out.toString("UTF-8"));}finally{h.disconnect();}}
 private static void sweep(){try{JSONArray ids=new JSONArray(Store.get("unpairIds","[]"));for(int i=0;i<ids.length();i++){JSONObject t=load(ids.getString(i));if(t==null||!t.optBoolean("pending"))continue;long now=System.currentTimeMillis();if(now<t.optLong("due"))continue;try{acknowledged(post(t.getJSONObject("peer"),"/pairing/unpair",t.getJSONObject("notice")));}catch(Exception e){synchronized(Store.class){JSONObject latest=load(ids.getString(i));if(latest!=null&&latest.getJSONObject("notice").getString("event").equals(t.getJSONObject("notice").getString("event"))){int tries=Math.min(5,t.optInt("tries")+1);latest.put("tries",tries).put("due",now+Math.min(300000,5000*(1<<tries)));Store.durable(slot(ids.getString(i)),latest.toString());}}}}}catch(Exception ignored){}}
}
